local factions = {
	["Sha'tari Skyguard"] = 1031,
	["Netherwing"] = 1015,
	["Honor Hold"] = 946,
	["The Violet Eye"] = 967,
	["The Mag'har"] = 941,
	["Kurenai"] = 978,
	["Shattered Sun Offensive"] = 1077,
	["Argent Dawn"] = 529,
	["Sporeggar"] = 970,
	["Timbermaw Hold"] = 576,
	["The Scale of the Sands"] = 990,
	["Zandalar Tribe"] = 270,
	["Cenarion Circle"] = 609,
	["Thorium Brotherhood"] = 59,
	["Brood of Nozdormu"] = 910,
	["Hydraxian Waterlords"] = 749,
	["Tranquillien"] = 922,
	["Ashtongue Deathsworn"] = 1012,
};
for i,o in pairs(ItemDB) do
	if o.minReputation then
		local faction = o.minReputation[1];
		if type(faction) == "string" then
			if faction == "Horde" then
				-- ignore it
			elseif not factions[faction] then
				print("WRONG REP TYPE", faction);
				factions[faction] = faction;
				o.minReputation = nil;
			else
				o.minReputation[1] = factions[faction];
			end
		end
	end

	-- This part only exists for us to find weird items.
	if o.otherRequirements then
		o.otherRequirements = nil;
	end
end
